// The TypeScript client's event stream reader over generated byte streams, for the Rust reader's differential test
// (crates/api/tests/all/sse.rs). Reads one case per standard input line, `{ "chunks": [<base64>, ...] }`, and writes
// one line per case: the events, each as `JSON.stringify` with lone surrogates as U+FFFD, and the reason of the error
// that ended the stream, if any. Writes no fixture.
// The generated client's reader, without the event wrapper of `OpenCode.make`.
import { make } from "../../../client/src/promise/generated/client"

const wellFormed = (_key: string, value: unknown) => (typeof value === "string" ? value.toWellFormed() : value)
const lines = (await Bun.stdin.text()).split("\n").filter((line) => line !== "")
const out: string[] = []
for (const line of lines) {
  const chunks = (JSON.parse(line).chunks as string[]).map((chunk) => Buffer.from(chunk, "base64"))
  const api = make({
    baseUrl: "http://opencode.local",
    fetch: async () =>
      new Response(
        new ReadableStream({
          pull(controller) {
            const chunk = chunks.shift()
            if (chunk === undefined) return controller.close()
            controller.enqueue(new Uint8Array(chunk))
          },
        }),
        { headers: { "content-type": "text/event-stream" } },
      ),
  })
  const events: string[] = []
  let error: string | null = null
  try {
    for await (const event of api.event.subscribe()) events.push(JSON.stringify(event, wellFormed))
  } catch (cause) {
    error = (cause as { reason?: string }).reason ?? String(cause)
  }
  out.push(JSON.stringify({ events, error }))
}
await Bun.write(Bun.stdout, out.join("\n") + "\n")
